137	// renderMemoryOperationReceiptText is the plain-output counterpart to the
138	// JSON receipt. Keep it content-free but complete enough for operators and
139	// scripts to retain the same operation identity and per-artifact transitions.
140	func renderMemoryOperationReceiptText(out io.Writer, receipt memoryOperationReceipt, status string) {
141		fmt.Fprintf(out, "%s %s schema_version=%d operation_id=%s dry_run=%v error_code=%s started_at=%s finished_at=%s artifacts=%d jobs=%d\n",
142			receipt.Operation, status, receipt.SchemaVersion, receipt.OperationID, receipt.DryRun, receipt.ErrorCode,
143			receipt.StartedAt.UTC().Format(time.RFC3339Nano), receipt.FinishedAt.UTC().Format(time.RFC3339Nano), len(receipt.Artifacts), len(receipt.JobIDs))
144		if receipt.SessionRef != "" {
145			fmt.Fprintf(out, "selected session_ref=%q\n", receipt.SessionRef)
146		}
147		for _, jobID := range receipt.JobIDs {
148			fmt.Fprintf(out, "selected job_id=%q\n", jobID)
149		}
150		for _, artifact := range receipt.Artifacts {
151			fmt.Fprintf(out, "artifact path=%q prior_state=%q new_state=%q\n", artifact.Path, artifact.PriorState, artifact.NewState)
152		}
153	}
