			!strings.Contains(out, "schema_version=1") || !strings.Contains(out, "operation_id=op:") ||
			!strings.Contains(out, "finished_at=") || !strings.Contains(out, legacyResult) {
			t.Fatalf("%s plain success receipt = %q", operation, out)
