	t.Run("migrate", func(t *testing.T) {
		opts, brainDir := memoryAdminCommandFixture(t)
		addMemoryAdminConversationFixture(t, brainDir, time.Date(2026, 8, 10, 8, 2, 0, 0, time.UTC))
