			return false, true, lines
		}
		if attempt == 0 {
			fmt.Fprintln(out, r.Line(Line{Text: "Please answer y or n.", Accent: PhaseFacts.Accent()}))
			lines++
		}
		if err != nil {
			fmt.Fprintln(out)
			return false, true, lines
		}
	}
	return false, true, lines
}

